import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"الحضارة التعددية لأمريكا الشمالية","description":"","frontmatter":{},"headers":[],"relativePath":"ar/33-北美多元型文明.md","filePath":"ar/33-北美多元型文明.md","lastUpdated":null}'),o={name:"ar/33-北美多元型文明.md"};function e(n,t,d,h,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="الحضارة-التعددية-لأمريكا-الشمالية" tabindex="-1">الحضارة التعددية لأمريكا الشمالية <a class="header-anchor" href="#الحضارة-التعددية-لأمريكا-الشمالية" aria-label="Permalink to &quot;الحضارة التعددية لأمريكا الشمالية&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>33</td></tr><tr><td>الوحدة</td><td>أنماط الحضارة والأنظمة الاجتماعية</td></tr><tr><td>الكلمات المفتاحية</td><td>تعددي أمريكا الشمالية، حرية وتنوع، تكافؤ فرص، منافسة سوق، دفع بالابتكار</td></tr></tbody></table><h2 id="أولاً-نشأة-الحضارة-التعددية-لأمريكا-الشمالية-وفكرتها-الجوهرية" tabindex="-1">أولاً: نشأة الحضارة التعددية لأمريكا الشمالية وفكرتها الجوهرية <a class="header-anchor" href="#أولاً-نشأة-الحضارة-التعددية-لأمريكا-الشمالية-وفكرتها-الجوهرية" aria-label="Permalink to &quot;أولاً: نشأة الحضارة التعددية لأمريكا الشمالية وفكرتها الجوهرية&quot;">​</a></h2><p>الحضارة التعددية لأمريكا الشمالية أكثر الأنماط الخمسة حرية، ويمكن رد نشأتها إلى التقاليد الحضارية لمناطق أمريكا الشمالية في العالم الواقعي (الولايات المتحدة وكندا أساساً). عبر قرون من التطور، تكونت في أمريكا الشمالية خصائص حضارية مركزها الحرية الفردية والمنافسة السوقية والشمول التعددي. بعد قيام حضارة التكافل المرساة، امتزجت هذه التقاليد بمفاهيم التكافل، وارتقيت إلى «الحضارة التعددية لأمريكا الشمالية».</p><p>تتخلص الفكرة الجوهرية في اثنتي عشرة كلمة: «حرية وتنوع، تكافؤ فرص». تفصيلاً:</p><ol><li><strong>الحرية الفردية</strong>: أعلى قيمة؛ لكل مزارع حق اختيار منظومة الزراعة وطريق التطور ونمط الحياة والتنظيم الاجتماعي بحرية، بلا تدخل غير معقول</li><li><strong>الشمول التعددي</strong>: احترام الاختلافات بين الأعراق والثقافات والمعتقدات وأنماط الحياة، وتشجيع التنوع؛ تعايش متساوٍ بين مزارعي الأعراق والمنظومات المختلفة</li><li><strong>تكافؤ الفرص</strong>: رغم فجوات الثروة والمراتب، لكل إنسان بداية متساوية وفرص متساوية؛ لا يكون المولد والأصل والمكانة حواجز</li><li><strong>المنافسة والابتكار</strong>: المنافسة الحرة توقظ كامن الفرد وإبداع المجتمع، محققة التوزيع الأمثل للموارد والابتكار المتواصل</li></ol><p>هذه المفاهيم متوافقة توافقاً عالياً مع مفاهيم الحضارة التكافلية: «النمو الذاتي» يؤكد حرية الفرد ومسؤوليته، و«طريق لكل إنسان» يؤكد ضمان تكافؤ الفرص، و«من عمل أكثر نال أكثر» يؤكد حافز المنافسة العادلة.</p><h2 id="ثانياً-البنية-الاجتماعية-للحضارة-التعددية-لأمريكا-الشمالية" tabindex="-1">ثانياً: البنية الاجتماعية للحضارة التعددية لأمريكا الشمالية <a class="header-anchor" href="#ثانياً-البنية-الاجتماعية-للحضارة-التعددية-لأمريكا-الشمالية" aria-label="Permalink to &quot;ثانياً: البنية الاجتماعية للحضارة التعددية لأمريكا الشمالية&quot;">​</a></h2><p>تتسم البنية بأربع خصائص أساسية: «حكومة ضعيفة + مجتمع قوي + اقتصاد سوق + شبكة أمان»:</p><table tabindex="0"><thead><tr><th>العنصر البنيوي</th><th>وصف الخصائص</th><th>الوظيفة الجوهرية</th></tr></thead><tbody><tr><td>الحكومة الضعيفة</td><td>حكومة محدودة الحجم والوظيفة؛ حفظ النظام وتقديم السلع العامة</td><td>إطار مؤسسي أساسي</td></tr><tr><td>المجتمع القوي</td><td>منظمات المجتمع المدني والمجتمعات المحلية وجماعات المصالح مزدهرة جداً</td><td>تحمل كثير من الحكم الذاتي والخدمات</td></tr><tr><td>اقتصاد السوق</td><td>السوق يوزع معظم الموارد؛ ملكية واضحة ومنافسة حرة</td><td>توزيع كفؤ للموارد</td></tr><tr><td>شبكة الأمان</td><td>شبكة حماية اجتماعية محدودة للمحرومين</td><td>ضمان حق البقاء والتطور</td></tr></tbody></table><h3 id="_2-1-الحكومة-الضعيفة" tabindex="-1">2.1 الحكومة الضعيفة <a class="header-anchor" href="#_2-1-الحكومة-الضعيفة" aria-label="Permalink to &quot;2.1 الحكومة الضعيفة&quot;">​</a></h3><p>«حكومة محدودة» نموذجية مسؤولة عن:</p><ul><li>حفظ النظام والأمن العام وحماية الأرواح والأموال</li><li>سلع عامة: بنى المراسي وقنوات الطاقة والقوانين الكلية</li><li>نظام السوق العادل؛ منع الاحتكار والمنافسة غير المشروعة</li><li>شبكة أمان محدودة للمحرومين</li></ul><p>الفكرة الجوهرية «الحكومة حارس ليلي للمجتمع» — لا تتدخل في حياة الفرد وسير المجتمع، بل تضمن الإطار الأساسي.</p><h3 id="_2-2-المجتمع-القوي" tabindex="-1">2.2 المجتمع القوي <a class="header-anchor" href="#_2-2-المجتمع-القوي" aria-label="Permalink to &quot;2.2 المجتمع القوي&quot;">​</a></h3><p>مجتمع مدني مزدهر جداً:</p><ul><li><strong>المجتمعات المحلية</strong>: استقلالية عالية؛ خدمات وتعاون جارٍ وحكم محلي</li><li><strong>الجمعيات المهنية</strong>: معايير الصناعة، وشهادات مهنية، وتنظيم التبادل</li><li><strong>جماعات المصالح</strong>: حماية حقوق الأعضاء بالعمل الجماعي</li><li><strong>المؤسسات والجمعيات الخيرية</strong>: تمويل العلم والتعليم والعمل النافع</li></ul><p>«دولة صغيرة، مجتمع كبير».</p><h3 id="_2-3-اقتصاد-السوق" tabindex="-1">2.3 اقتصاد السوق <a class="header-anchor" href="#_2-3-اقتصاد-السوق" aria-label="Permalink to &quot;2.3 اقتصاد السوق&quot;">​</a></h3><ul><li><strong>الملكية الواضحة</strong>: حماية صارمة للممتلكات والإنجازات</li><li><strong>المنافسة الحرة</strong>: دخول وخروج حر، وتدفق الموارد بالسوق</li><li><strong>روح العقد</strong>: تعاملات طوعية وتنفيذ صارم</li><li><strong>ثقافة المبادرة</strong>: تشجيع المخاطرة وتقبل الفشل</li></ul><p>السعر والمنافسة والحافز — توزيع كفؤ.</p><h2 id="ثالثاً-النمط-الزراعي-للحضارة-التعددية-لأمريكا-الشمالية" tabindex="-1">ثالثاً: النمط الزراعي للحضارة التعددية لأمريكا الشمالية <a class="header-anchor" href="#ثالثاً-النمط-الزراعي-للحضارة-التعددية-لأمريكا-الشمالية" aria-label="Permalink to &quot;ثالثاً: النمط الزراعي للحضارة التعددية لأمريكا الشمالية&quot;">​</a></h2><p>الخصائص الجوهرية: «اختيار حر، انتقاء تنافسي، مسارات متنوعة»:</p><h3 id="_3-1-الاختيار-الحر-للمنظومات" tabindex="-1">3.1 الاختيار الحر للمنظومات <a class="header-anchor" href="#_3-1-الاختيار-الحر-للمنظومات" aria-label="Permalink to &quot;3.1 الاختيار الحر للمنظومات&quot;">​</a></h3><p>الأنظمة الأصلية الثلاثمائة مفتوحة للجميع؛ يختار المزارع حسب اهتمامه وموهبته وهدفه. لا «مسار معياري» — كلٌّ يشق طريقه.</p><h3 id="_3-2-الانتقاء-التنافسي" tabindex="-1">3.2 الانتقاء التنافسي <a class="header-anchor" href="#_3-2-الانتقاء-التنافسي" aria-label="Permalink to &quot;3.2 الانتقاء التنافسي&quot;">​</a></h3><p>رغم الحرية، تبقى المنافسة — عادلة وشفافة بقواعد واضحة:</p><ul><li>المنافسة على حصص الموارد</li><li>القبول في الطوائف والمعاهد</li><li>حقول عقد التقدم</li><li>مناصب المشاريع الكبرى</li></ul><h3 id="_3-3-المسارات-المتنوعة" tabindex="-1">3.3 المسارات المتنوعة <a class="header-anchor" href="#_3-3-المسارات-المتنوعة" aria-label="Permalink to &quot;3.3 المسارات المتنوعة&quot;">​</a></h3><ul><li>الزراعة الطائفية، والمعاهدية، والمستقلة، وبإرشاد المرشد، والمختلطة — أيّها شاء</li><li>اختيار بحسب الأحوال؛ تحقيق أقصى الكامن</li></ul><h3 id="_3-4-ثقافة-الابتكار" tabindex="-1">3.4 ثقافة الابتكار <a class="header-anchor" href="#_3-4-ثقافة-الابتكار" aria-label="Permalink to &quot;3.4 ثقافة الابتكار&quot;">​</a></h3><p>تشجيع الابتكار الزراعي: طرق جديدة، وطاقة جديدة، وتقنيات حضارية جديدة؛ براءات الاختراع والأوسمة — مكافآت سخية.</p><h2 id="رابعاً-آلية-عقد-الإنتاج-المرتبط-للحضارة-التعددية-لأمريكا-الشمالية" tabindex="-1">رابعاً: آلية عقد الإنتاج المرتبط للحضارة التعددية لأمريكا الشمالية <a class="header-anchor" href="#رابعاً-آلية-عقد-الإنتاج-المرتبط-للحضارة-التعددية-لأمريكا-الشمالية" aria-label="Permalink to &quot;رابعاً: آلية عقد الإنتاج المرتبط للحضارة التعددية لأمريكا الشمالية&quot;">​</a></h2><p>شكلها الرئيس «العقد السوقي»:</p><ol><li><strong>العقد الفردي</strong>: المزارع فرداً يتعاقد مباشرة؛ ملكية ومسؤولية واضحتان</li><li><strong>تسعير السوق</strong>: الدخل بالعرض والطلب؛ قيمة الإنجاز السوقية تحدد العائد</li><li><strong>حماية الشبكة</strong>: شبكة أمان محدودة للمحرومين</li><li><strong>العائد الريادي</strong>: مشاريع عالية المخاطر عالية العائد؛ ربح كبير وخطر كبير</li></ol><p>الميزة: إطلاق كامل للمبادرة والإبداع، وكفاءة في التوزيع؛ مع فجوة ثروات محدودة تحفظها الشبكة.</p><h2 id="خامساً-مزايا-الحضارة-التعددية-لأمريكا-الشمالية-وتحدياتها" tabindex="-1">خامساً: مزايا الحضارة التعددية لأمريكا الشمالية وتحدياتها <a class="header-anchor" href="#خامساً-مزايا-الحضارة-التعددية-لأمريكا-الشمالية-وتحدياتها" aria-label="Permalink to &quot;خامساً: مزايا الحضارة التعددية لأمريكا الشمالية وتحدياتها&quot;">​</a></h2><h3 id="_5-1-المزايا-النموذجية" tabindex="-1">5.1 المزايا النموذجية <a class="header-anchor" href="#_5-1-المزايا-النموذجية" aria-label="Permalink to &quot;5.1 المزايا النموذجية&quot;">​</a></h3><ul><li><strong>ابتكار قوي</strong>: بيئة المنافسة الحرة تحفز بقوة</li><li><strong>حيوية وفيرة</strong>: الثقافة التعددية والمنافسة الحرة</li><li><strong>حرية فردية عالية</strong>: أقصى كامن بإرادة الفرد</li><li><strong>جاذبية قوية</strong>: ثقافة منفتحة تجذب مواهب الكون</li></ul><h3 id="_5-2-التحديات" tabindex="-1">5.2 التحديات <a class="header-anchor" href="#_5-2-التحديات" aria-label="Permalink to &quot;5.2 التحديات&quot;">​</a></h3><ul><li><strong>فجوة ثروات كبيرة</strong>: المنافسة الحرة توسعها فتهدد العدالة</li><li><strong>تماسك اجتماعي منخفض</strong>: الإفراط في الفردية يوهن الجماعة</li><li><strong>خطر التسليع</strong>: منطق السوق يتسرب إلى غير السوق</li><li><strong>حماية أساسية أضعف</strong>: الشبكة المحدودة لا تكفي المحرومين حقاً</li></ul><p>للمواجهة، تمتص مزايا الأنماط الأخرى: آلية الحماية الشاملة للشمالي الأوروبي، وآلية التنسيق الجماعي للمكثف الشرقي؛ توازن بين الحرية والعدالة، والمنافسة والتعاون.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>الحضارة التعددية لأمريكا الشمالية أكثر أنماط حضارة التكافل المرساة حرية. بفكرة «حرية وتنوع، تكافؤ فرص»، وببنية الحكومة الضعيفة والمجتمع القوي واقتصاد السوق وشبكة الأمان، وبالنمط الزراعي الحر الاختيار، وبآلية العقد السوقي، حققت ابتكاراً قوياً وحيوية وفيرة. مع الحفاظ على خصوصيتها، تبحث باستمرار عن أفضل توازن بين الحرية والنظام، والمنافسة والتعاون.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (نظرة شاملة على الأنماط الخمسة للحضارة التكافلية)</li><li>34-欧洲大陆社会型文明 (الحضارة الاجتماعية لأوروبا القارية)</li><li>36-社会结构与阶层流动 (البنية الاجتماعية وحراك الطبقات)</li></ul>',46)])])}const c=a(o,[["render",e]]);export{_ as __pageData,c as default};
